import sys,re,json,hashlib,datetime
from pathlib import Path
from collections import Counter,defaultdict
sys.path.insert(0,'/tmp/cad-dxf-libs')
import ezdxf
from ezdxf import bbox
from ezdxf.disassemble import recursive_decompose

out=Path(__file__).parent
origin=(0.0,0.0)
def decode(s):
    return re.sub(r'\\M\+5([0-9A-Fa-f]{4})',lambda m:bytes.fromhex(m[1]).decode('gbk'),s)
summaries={}
for p in sorted((out/'source_dxf').glob('*.dxf')):
    d=ezdxf.readfile(p);m=d.modelspace()
    for e in d.entitydb.values():
        if e.dxftype() in ('TEXT','ATTRIB','ATTDEF'):e.dxf.text=decode(e.dxf.text)
        elif e.dxftype()=='MTEXT':e.text=decode(e.text)
    counts=defaultdict(Counter);texts=[];dims=[]
    for e in m:
        counts[e.dxf.layer][e.dxftype()]+=1
        if e.dxftype() in ('TEXT','MTEXT'):
            pos=e.dxf.insert
            texts.append({'type':e.dxftype(),'text':e.plain_text(),'xy':[pos.x,pos.y],'layer':e.dxf.layer,'handle':e.dxf.handle,'height':e.dxf.get('height',e.dxf.get('char_height',0))})
        elif e.dxftype()=='DIMENSION':
            dims.append({'value':e.get_measurement(),'text':e.dxf.text,'type':e.dxf.dimtype,'handle':e.dxf.handle,'p1':list(e.dxf.get('defpoint2',(0,0,0))),'p2':list(e.dxf.get('defpoint3',(0,0,0)))})
    summaries[p.stem]={'counts':dict(counts),'texts':texts,'dimensions':dims,
        'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),
        'frozen_layers':[l.dxf.name for l in d.layers if l.is_off() or l.is_frozen()]}
(out/'source_inventory.json').write_text(json.dumps(summaries,ensure_ascii=False,indent=2))
print('ELEVATION/SECTION TEXT:')
for name,s in summaries.items():
    if name[:2] in ['28','29','30','31','32','33']:
        print(name,[(t['text'],[round(v,1) for v in t['xy']]) for t in s['texts'] if t['text'].strip()])
print('GROUND LAYERS:',summaries['20小学首层']['counts'])
print('GROUND LABELS:',[(t['text'],[round(t['xy'][i]-origin[i],1) for i in [0,1]]) for t in summaries['20小学首层']['texts'] if t['text'].strip()])

